<script setup lang="ts">
/**
 * The page for a query and its results (`design/archetypes/search-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/search-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed } from 'vue'

import { useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/search-page.module.css'
import EmptyState, { type EmptyStateProps } from '../structure/EmptyState.vue'
import Inline from '../layout/Inline.vue'
import PageHeader from '../structure/PageHeader.vue'

export interface SearchPageProps {
  description?: string
  /**
   * The query found nothing: the results region holds the empty state.
   */
  empty?: boolean
  /**
   * The empty state, required so the page always says what it shows when a query finds nothing.
   */
  emptyState: EmptyStateProps
  /**
   * A search is running: the results region is busy, and the last results stay in it.
   */
  pending?: boolean
  /**
   * The search landmark's name. A shell often has a search of its own, and two landmarks of one
   * kind are told apart only by their names.
   */
  searchLabel: string
  title: string
}

defineOptions({ name: 'SearchPage', inheritAttrs: false })

withDefaults(defineProps<SearchPageProps>(), { empty: false, pending: false })
const emit = defineEmits<{ submit: [] }>()
defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  default?: (props: Record<string, never>) => unknown
  filters?: (props: Record<string, never>) => unknown
  search: (props: Record<string, never>) => unknown
}>()
const listening = useListening()
const submit = computed(() => (event: Event) => {
  event.preventDefault()
  emit('submit')
})
</script>

<template>
  <div
    :class="styles.page"
    :data-empty="empty ? '' : undefined"
    :data-pending="pending ? '' : undefined"
    data-member="search-page"
  >
    <PageHeader :title="title" :description="description">
      <template v-if="$slots.actions" #actions>
        <slot name="actions" />
      </template>
    </PageHeader>
    <!-- search -->
    <form
      v-if="listening.submit"
      :class="styles.search"
      role="search"
      :aria-label="searchLabel"
      data-search-page-part="search"
      :novalidate="true"
      @submit="submit($event)"
    >
      <slot name="search" />
      <Inline v-if="$slots.filters" :gap="3" :wrap="true">
        <slot name="filters" />
      </Inline>
    </form>
    <!-- search -->
    <div
      v-else
      :class="styles.search"
      role="search"
      :aria-label="searchLabel"
      data-search-page-part="search"
    >
      <slot name="search" />
      <Inline v-if="$slots.filters" :gap="3" :wrap="true">
        <slot name="filters" />
      </Inline>
    </div>
    <!-- results -->
    <div
      :class="styles.results"
      :aria-busy="pending ? true : undefined"
      data-search-page-part="results"
    >
      <EmptyState
        v-if="empty"
        :icon="emptyState.icon"
        :title="emptyState.title"
        :description="emptyState.description"
      >
        <template v-if="emptyState.action !== undefined" #action>
          <component :is="emptyState.action" />
        </template>
        <template v-if="emptyState.secondaryAction !== undefined" #secondaryAction>
          <component :is="emptyState.secondaryAction" />
        </template>
      </EmptyState>
      <template v-else>
        <slot />
      </template>
    </div>
  </div>
</template>
